# Transfer a person to another sheet (see TransferPerson): they arrive there with their grades, terms, contact,
# aliases and claims, merged into the person there of the same name or alias when there is one, and leave this sheet
# entirely; both sheets' figures follow. A refused transfer (no signed-in user, not a steward, unknown person,
# retired, this sheet's own id, an archived sheet, their names or aliases held by more than one person there, the
# person merged into retired, or, with no one to merge into, their contact already there) writes nothing, not even
# an audit line.
validate:
  class: net.officefloor.hq.app.person.ValidateTransfer
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: transfer
transfer:
  class: net.officefloor.hq.app.person.TransferPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPersonTransferred
  govern: [ transaction ]
  next: respond
