package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Refuse undoing the transfer unless a steward asks on the sheet-today the loaded person arrived on this sheet by
 *  transfer; otherwise it goes ahead as a transfer back to the sheet they came from. */
public class RefuseTransferUndo {
    public void refuse(@Val TransferUndoRequest request, @Val Person loaded, PersonRepository people,
            RoleRepository roles, SheetRepository sheets, Out<TransferInput> transfer) throws InvalidPersonException {
        String sheetId = loaded.sheetId();
        if (!Role.STEWARD.equals(roles.of(sheetId, request.user()))) {
            throw new InvalidPersonException("Only a steward may undo a transfer.");
        }
        LocalDate arrived = people.arrivedOn(sheetId, loaded.id());
        if (loaded.origin() == null || arrived == null) {
            throw new InvalidPersonException(loaded.name() + " did not arrive here by transfer.");
        }
        if (!arrived.equals(sheets.today(sheetId))) {
            throw new InvalidPersonException(loaded.name() + "'s transfer can be undone only on the day they arrived ("
                    + arrived + ").");
        }
        transfer.set(new TransferInput(request.user(), loaded.origin()));
    }
}
EOF
cat > $P/AuditPersonTransferUndone.java <<'EOF'
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.plugin.variable.Val;

/** Record on this sheet that the transfer was undone (after the transfer back's own records), then how its figures
 *  moved. */
public class AuditPersonTransferUndone {
    public void audit(@Val TransferInput input, @Val Transfer transfer, @Val Rollup before, Audit audit,
            Rollups rollups) {
        audit.record("PERSON_TRANSFER_UNDONE sheet=" + transfer.fromSheet() + " by=" + input.user() + " name="
                + transfer.name() + " to=" + transfer.toSheet());
        rollups.record(transfer.fromSheet(), input.user(), before);
    }
}
EOF
cat > "resources/officefloor/rest/api/sheets/{sheetId}/people/{personId}/transfer-undo.POST.yml" <<'EOF'
# Undo the transfer that brought a person to this sheet: only a steward, only on the sheet-today they arrived, only a
# person who arrived by transfer. They are transferred back to the sheet they came from exactly as a transfer (see
# TransferPerson, with its refusals and audit lines), and this sheet then records PERSON_TRANSFER_UNDONE. A refused undo
# writes nothing, not even an audit line.
validate:
  class: net.officefloor.hq.app.person.ValidateTransferUndo
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: refuse
refuse:
  class: net.officefloor.hq.app.person.RefuseTransferUndo
  govern: [ transaction ]
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: transfer
transfer:
  class: net.officefloor.hq.app.person.TransferPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPersonTransferred
  govern: [ transaction ]
  next: undone
undone:
  class: net.officefloor.hq.app.person.AuditPersonTransferUndone
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
EOF
cat > frontend/features/people/transferundo.slot.tsx <<'EOF'
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonRow } from '../../slots/defs/personRow';
import { usePersonError } from './rowError';
import type { Person } from './people';

/** The button that undoes the transfer that brought the person here (a steward only, on the sheet-today they
 *  arrived): they are transferred back to the sheet they came from, and leave the list. */
function PersonTransferUndo({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const { error, setError, begin } = usePersonError(sheetId, person.id);
  const once = useSubmitOnce();

  const undo = useMutation({
    mutationFn: () =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/transfer-undo`, { user }),
    onSuccess: async () => {
      // the person and their claims go back to the sheet they came from: everything shown of both follows
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] }),
        ...(person.origin ? [queryClient.invalidateQueries({ queryKey: ['sheet', person.origin] })] : []),
      ]);
    },
    onError: (e) =>
      setError(e instanceof HttpError && e.body ? e.body : `Could not undo the transfer of ${person.name}.`),
    onSettled: once.done,
  });

  return (
    <td>
      <button
        type="button"
        data-testid="person-transfer-undo"
        disabled={undo.isPending}
        onClick={() => {
          begin();
          if (!once.start()) return;
          undo.mutate();
        }}
      >
        Undo transfer
      </button>
      {error && (
        <p data-testid="person-error" role="alert">
          {error}
        </p>
      )}
    </td>
  );
}

export const contribution = PersonRow.fill({ order: 50, Component: PersonTransferUndo });
EOF
